require_once dirname(__DIR__).'/includes/functions.php';require_role('counselor');verify_csrf();$id=(int)($_POST['id']??0);$status=$_POST['status']??'';$feedback=trim($_POST['feedback']??'');$allowed=['under_review','shortlisted','unsuccessful','accepted'];
if(!in_array($status,$allowed,true)||!$feedback||mb_strlen($feedback)>3000)json_response(['ok'=>false,'message'=>'Choose a valid status and provide feedback (maximum 3,000 characters).'],422);
$stmt=$con->prepare('SELECT a.user_id,j.title FROM job_applications a JOIN job_opportunities j ON j.id=a.job_id WHERE a.id=?');$stmt->bind_param('i',$id);$stmt->execute();$app=$stmt->get_result()->fetch_assoc();if(!$app)json_response(['ok'=>false,'message'=>'Application not found.'],404);
$reviewer=(int)user()['id'];$stmt=$con->prepare('UPDATE job_applications SET status=?,reviewer_feedback=?,reviewed_by=?,reviewed_at=NOW() WHERE id=?');$stmt->bind_param('ssii',$status,$feedback,$reviewer,$id);$stmt->execute();notify_user($con,(int)$app['user_id'],'job_feedback','Your '.$app['title'].' application was updated to '.str_replace('_',' ',$status).'. Feedback is available in My applications.');json_response(['ok'=>true,'message'=>'Review saved and student notified.','reload'=>true]);
